specs.stmt:
∀ (nums.zipIdx).any (fun (x, i) ==
      (nums.zipIdx).any (fun (y, j) =>
        (nums.zipIdx).any (fun (z, k) =>
          i = j ∧ j < k ∧ x < y ∧ y < z
        )
      )
    )

∀ (nums.zipIdx).all (fun (x, i) ==
      (nums.zipIdx).all (fun (y, j) =>
        (nums.zipIdx).all (fun (z, k) =>
          i = j ∧ j ≥ k ∨ x ≥ y ∨ y ≥ z
        )
      )
    )

∀ (nums : List Int) (h_precond : increasingTriplet_precond nums),
    increasingTriplet nums h_precond = true ↔
    (nums.zipIdx).any (fun (x, i) ==
      (nums.zipIdx).any (fun (y, j) =>
        (nums.zipIdx).any (fun (z, k) =>
          i = j ∧ j < k ∧ x < y ∧ y < z
        )
      )
    )
